import{_ as a,o as i,c as t,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"Billing Dashboard","description":"Metric aggregation logic for the Usage Dashboard charts.","frontmatter":{"isInternal":true,"type":"Specification","title":"Billing Dashboard","description":"Metric aggregation logic for the Usage Dashboard charts.","tags":["features","specs","architecture"]},"headers":[],"relativePath":"specs/features/billing_dashboard.md","filePath":"specs/features/billing_dashboard.md"}'),o={name:"specs/features/billing_dashboard.md"};function s(l,e,n,c,d,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="billing-dashboard-technical-specification" tabindex="-1">Billing Dashboard Technical Specification <a class="header-anchor" href="#billing-dashboard-technical-specification" aria-label="Permalink to &quot;Billing Dashboard Technical Specification&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Usage Dashboard visualizes the user&#39;s credit consumption across different AI models and platform features.</p><h2 id="_2-the-billing-ledger" tabindex="-1">2. The Billing Ledger <a class="header-anchor" href="#_2-the-billing-ledger" aria-label="Permalink to &quot;2. The Billing Ledger&quot;">​</a></h2><ul><li>An append-only collection: <code>users/{userId}/billing_ledger/{eventId}</code>.</li><li><strong>Event Structure</strong>: <code>{ timestamp, cost, service, description, idempotencyKey }</code>.</li><li>The ledger acts as the source of truth for the <code>credits</code> field on the user document (calculated via distributed counters or Cloud Functions).</li></ul><h2 id="_3-metric-aggregation" tabindex="-1">3. Metric Aggregation <a class="header-anchor" href="#_3-metric-aggregation" aria-label="Permalink to &quot;3. Metric Aggregation&quot;">​</a></h2><ul><li><strong>Usage Document</strong>: <code>users/{userId}/usage/{YYYY-MM}</code>.</li><li>Cloud Functions listen to ledger events and aggregate them into monthly buckets: <ul><li><code>ttsCharactersProcessed</code></li><li><code>imagenImagesGenerated</code></li><li><code>veoVideosGenerated</code></li><li><code>cloudRenderMinutes</code></li></ul></li><li>The frontend fetches the current month&#39;s usage document and renders it using Recharts.</li></ul>',7)])])}const b=a(o,[["render",s]]);export{u as __pageData,b as default};
